\label{ChernEq}
Let $P^2$ be  a complete immersed minimal surface in $\mathbb{H}^n(b)$. Let us suppose that $\int_P \Vert B^P\Vert^2 d\sigma < \infty$. Then
\begin{equation}\label{Equality}
-\chi(P)=\frac{1}{4\pi}\int_P \Vert B^P \Vert ^ 2 d\sigma-\operatorname{Sup}_{t>0}\frac{\operatorname{Vol}(D_t)}{\operatorname{Vol}(B_t^{b,2})}-\frac{1}{2\pi}G_b(P)
\end{equation}
where $G_b(P)$ is a nonnegative and finite quantity which do not depends on the exhaustion by extrinsic balls $\{D_t\}_{t>0}$ of $P$ and is given by
\begin{equation}
\begin{aligned}
G_b(P)&:= \lim_{t \to \infty}\left(h_b(t)\operatorname{Vol}(B^{b,2}_t)(\frac{(\operatorname{Vol}(D_t))}{\operatorname{Vol}(B^{b,2}_t)})' \right.\\&\left.+\int_{\partial D_t} \langle B^P(e,e),\frac{\operatorname{\nabla}^\perp r}{\Vert \operatorname{\nabla}^P r \Vert}\rangle d\sigma_t\right)
\end{aligned}
\end{equation}

\label{theRemk1}
When the submanifold considered is totally geodesic, namely, when $P$ is a Hyperbolic or an Euclidean subespace of the ambient real space form, the extrinsic balls become geodesic balls, and its boundary is the distance sphere. We recall here that the mean curvature of the geodesic sphere in the real space form $\mathbb{K}^{n}(b)$, 'pointed inward' is (see \cite{Pa}):
$$
h_b(t)=\left\{
\begin{array}{l}
\sqrt{b}\cot\sqrt{b}t\,\,\text{  if }\,\,b>0\\
1/t\,\,\text{  if }\,\, b=0\\
\sqrt{-b}\coth\sqrt{-b}t\,\, \text{  if }\,\, b<0
\end{array}\right.
$$

\label{geodCurv}
Given $\partial D_t$ the smooth closed curves in $P$, 

\begin{equation}\label{equ:kg}

k_g^{\partial D_t}=\frac{h_b(t)}{\Vert \operatorname{\nabla}^Pr\Vert}+\langle B^P(e,e),\frac{\operatorname{\nabla}^{\bot}r}{\Vert \operatorname{\nabla}^Pr\Vert}\rangle

\end{equation}

Let $\{e, \nu\} \subset TP$ be an orthonormal frame along the curve $\partial D_t$, where $e$ is the unit tangent vector to $\partial D_t$ and $\nu=\frac{\operatorname{\nabla}^P r}{\Vert \operatorname{\nabla}^P \Vert}$ is the unit normal to $\partial D_t$ in $P$, pointed outward. 


From the definition of geodesic curvature of the
extrinsic boundaries $\partial D_{t}$, we have
\begin{equation}
k_{g}^{t}=-\langle\nabla_{e}^{P}e,\frac{\nabla^{P}r}{\Vert\nabla^{P}r\Vert}\rangle
\end{equation}
Then, having on account the definition of Hessian
\[
Hess^{P}r(e,e)=\langle \nabla^{P}\nabla^{P}r,e\rangle
\]
and the fact that $\nabla^{P}r$ and $e$ are orthogonal,
\begin{equation}
k_{g}^{t}=\frac{1}{\Vert\nabla^{P}r\Vert}Hess^{P}r(e,e)
\end{equation}

But, given $X\in
T_{q}P$ unitary, (see \cite{HP} and \cite{Pa3} for detailed computations):
\begin{equation}  \label{eqHess1}

\operatorname{Hess}^P(r)(X,X)\, = \, h_b(r)\left(\, 1-  \langle\, X,\nabla^{\mathbb{K}^{n}(b)} r\,\rangle^{2} \, \right) +  \langle \, \nabla^{\mathbb{K}^{n}(b)}r, \, B^P(X,X) \, \rangle \,  

\end{equation}
where $B^P$ is the second fundamental form of $P$ in $N$. 
\bigskip
Applying at this point equation (\ref{eqHess1}):

\begin{equation}
k_{g}^{t}=\frac{1}{\Vert\nabla^{P}r\Vert}\{h_{b}(r)+\langle \nabla
^{\perp}r,B^{P}(e,e)\rangle\}
\end{equation}

\label{gradient}
Let $P^2\subset \mathbb{K}^{n}(b)$ be a  surface properly immersed in a real space form with curvature $b\leq 0$, let $D_t$ be an extrinsic disc in $P$ of radius $t >0$ and let $\partial D_t$ the extrinsic circle. Then: 
\begin{equation}\label{intgrad}
\int_{\partial D_t}\frac{||\nabla^\bot r||^2}{||\nabla^P r||}d\sigma_t\leq \int_{\partial D_t}\frac{1}{||\nabla^P r||}-h_b(t)\operatorname{Vol}(D_t)d\sigma_t
\end{equation}

Tracing equality (\ref{eqHess1}) we obtain the following expression for the Laplacian of the extrinsic distance in this context:

 \begin{equation} \label{eqLap1}

\Delta^{P}(r) \,= \, (m -\Vert \nabla^{P} r \Vert^{2})h_b(r)
 + m 
\langle \, \nabla^{N}r, \, H_{P}  \, \rangle  \quad ,

\end{equation}
where $H_{P}$ denotes the mean curvature vector
of $P$ in $N$ and $h_b(r)$ is the mean curvature of the geodesic $r$-spheres in $\mathbb{K}^{n}(b)$.
Applying divergence theorem  we have
\begin{equation}
\begin{aligned}
&\int_{\partial D_t}\frac{||\nabla^\bot r||^2}{||\nabla^P r||}d\sigma_t= \int_{\partial D_t}\frac{1}{||\nabla^P r||}d\sigma_t-\int_{\partial D_t}||\nabla^P r||d\sigma_t=\int_{\partial D_t}\frac{1}{||\nabla^P r||}d\sigma_t\\&-\int_{D_t}\Delta^P rd\sigma=\int_{\partial D_t}\frac{1}{||\nabla^P r||}d\sigma_t-\int_{D_t}(2-||\nabla^P r||^2)h_b(r)d\sigma\\&\leq \int_{\partial D_t}\frac{1}{||\nabla^P r||}d\sigma_t-
\int_{D_t}h_b(r)d\sigma\leq \int_{\partial D_t}\frac{1}{||\nabla^P r||}d\sigma_t-h_b(t)\operatorname{Vol}(D_t)
\end{aligned}
\end{equation}

\label{Mainth}
Let $P^2\subset \mathbb{K}^{n}(b)$ be a complete minimal surface properly immersed in a real space form with curvature $b\leq 0$, let $D_t$ be an extrinsic disc in $P$ of radius $t >0$ and let $\partial D_t$ be its boundary. Then: 
\begin{equation}
\begin{aligned}
-2\pi\chi &(D_t) +(b+\frac{f_{b,\alpha}^2(t)h_b(t)}{2 })\operatorname{Vol}(D_t)\\&+(h_b(t)-\frac{f_{b,\alpha}^2(t)}{2})\int_{\partial D_t} \frac{1}{\Vert \nabla^P r\Vert} d\sigma_t\leq \frac{1}{2}R(t)+\frac{1}{2 f_{b,\alpha}^2(t)}R'(t)
\end{aligned}
\end{equation}
\noindent where $R(t)=\int_{D_t}\Vert B^P\Vert^2 d\sigma$,  $\Vert B^P\Vert$ is the norm of the second fundamental form of $P$ in $\mathbb{K}^{n}(b)$, $\chi(D_t)$ is the Euler's characterisc of $D_t$ and, given  $\alpha \in ]0,2[$\, ,
$$
f_{b,\alpha}^2(t)=\alpha h_b(t)
$$

Integrating along $\partial D_t$ equation (\ref{equ:kg}) and using Gauss-Bonnet theorem and co-area formula, (see \cite{S}), we obtain
\begin{equation}
\begin{aligned}
2&\pi\chi (D_t) -\int_{D_t}K^P d\sigma=\\&h_b(t)\int_{\partial D_t}\frac{1}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t+
\int_{\partial D_t}\langle B^P(e,e),\frac{\operatorname{\nabla}^{\bot}r}{\Vert \operatorname{\nabla}^Pr\Vert}\rangle d\sigma_t\end{aligned}
\end{equation}
where we denote as $K^P$ the Gauss curvature of $P$.

But , on $\partial D_t$, 

$$-\Vert B^P\Vert \frac{\Vert \operatorname{\nabla}^{\bot}r\Vert}{\Vert \operatorname{\nabla}^Pr\Vert} \leq \langle B^P(e,e),\frac{\operatorname{\nabla}^{\bot}r}{\Vert \operatorname{\nabla}^Pr\Vert}\rangle \leq \Vert B^P\Vert \frac{\Vert \operatorname{\nabla}^{\bot}r\Vert}{\Vert \operatorname{\nabla}^Pr\Vert}$$

\noindent so, as $f_{b,\alpha}(t) \geq 0\,\forall t>0$,  having into account the inequality among the arithmetic and geometric mean and applying co-area formula:

\begin{equation}\label{bigineq}
\begin{aligned}
2&\pi\chi (D_t) -\int_{D_t}K^Pd\sigma=h_b(t)\int_{\partial D_t}\frac{1}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t\\&+\int_{\partial D_t}\langle B^P(e,e),\frac{\operatorname{\nabla}^{\bot}r}{\Vert \operatorname{\nabla}^Pr\Vert}\rangle d\sigma_t \, \geq\, h_b(t) \int_{\partial D_t}\frac{1}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t\\&-\frac{1}{2}\int_{\partial D_t}\frac{\Vert B^P\Vert ^2}{f_{b,\alpha}^2(r)\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t-\frac{1}{2} \int_{\partial D_t}\frac{f_{b,\alpha}^2(r)\Vert \operatorname{\nabla}^{\bot}r\Vert ^2}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t\\&\geq h_b(t) \int_{\partial D_t}\frac{1}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t-\frac{1}{2 f_{b,\alpha}^2(t)}R'(t)-\frac{f_{b,\alpha}^2(t)}{2}\int_{\partial D_t}\frac{\Vert \operatorname{\nabla}^{\bot}r\Vert ^2}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t
\end{aligned}
\end{equation}

Then, using inequality (\ref{intgrad}) of Lemma  \ref{gradient}  in the last member of the inequalities (\ref{bigineq}) and  applying Gauss equation for minimal surfaces in the real space forms $\mathbb{K}^{n}(b)$, we have

\begin{equation}
\begin{aligned}
2\pi\chi &(D_t) -b\operatorname{Vol}(D_t)+\frac{1}{2}R(t) \geq (h_b(t)-\frac{f_{b,\alpha}^2(t)}{2}) \int_{\partial D_t}\frac{1}{\Vert \operatorname{\nabla}^Pr\Vert}d\sigma_t\\ &-\frac{1}{2 f_{b,\alpha}^2(t)}R'(t)+\frac{f_{b,\alpha}^2(t)h_b(t)}{2 }\operatorname{Vol}(D_t)
\end{aligned}
\end{equation}
and hence

\begin{equation}
\begin{aligned}
-2\pi\chi& (D_t) +(b+\frac{f_{b,\alpha}^2(t)h_b(t)}{2 })\operatorname{Vol}(D_t)\\&+(h_b(t)-\frac{f_{b,\alpha}^2(t)}{2})\int_{\partial D_t} \frac{1}{\Vert \nabla^P r\Vert} \leq \frac{1}{2}R(t)+\frac{1}{2 f_{b,\alpha}^2(t)}R'(t)
\end{aligned}
\end{equation}
